        num.parse::<i64>(),
        match unit.trim() {
            "h" => Some(3600),
            "d" => Some(86_400),
            "w" => Some(7 * 86_400),
            _ => None,
        },
    ) {
        return Ok(crate::text::format_unix(now_secs + n.min(100_000) * secs));
    }
    match crate::text::normalize_date(raw) {
        Some(d) if d.len() == 10 => Ok(format!("{d}T23:59:59Z")),
        Some(d) => Ok(format!("{d}Z")),
