pub fn namespace(raw: &str) -> Result<String, Refused> {
    let ns = raw.trim().to_lowercase();
    if !NAMESPACE.is_match(&ns) {
        return refuse(format!(
            "namespace {raw:?}: use 1-64 of a-z 0-9 : _ . / @ -, e.g. `user`, `project:billing`, `agent:reviewer`"
        ));
    }
    Ok(ns)
